     private static final String ALLOW = "Allow";

     /**
-     * The JWK members that carry private or symmetric key material (RFC 7518 sections 6.2.2, 6.3.2
-     * and 6.4.1). A JWK holding any of them is refused at construction, so this endpoint can never
-     * publish one.
+     * The JWK members that carry private key material (RFC 7518 sections 6.2.2 and 6.3.2). They are
+     * stripped from the signing key's JWK at construction, so the endpoint publishes only the public
+     * half and the caller no longer has to derive it.
      */
-    private static final Set<String> PRIVATE_MEMBERS = Set.of("d", "p", "q", "dp", "dq", "qi", "oth", "k");
+    private static final Set<String> PRIVATE_MEMBERS = Set.of("p", "q", "dp", "dq", "qi", "oth");

     private final @Nullable Map<String, Object> document;

     /**
-     * Assembles the publishing form.
+     * Assembles the publishing form from the full JWK of the client-authentication key.
      *
-     * @param publicJwk the public JWK of the client-authentication key; its member order is kept
-     * @throws IllegalArgumentException when {@code publicJwk} carries a private or symmetric key
-     *                                  member
+     * @param signingJwk the JWK of the client-authentication key as the key material type exports
+     *                   it; private members are withheld, the member order of the rest is kept
      */
-    public ClientJwksEndpoint(Map<String, Object> publicJwk) {
-        Objects.requireNonNull(publicJwk, "publicJwk");
-        if (publicJwk.keySet().stream().anyMatch(PRIVATE_MEMBERS::contains)) {
-            // Fixed text: the offending member's value is key material and must not be echoed.
-            throw new IllegalArgumentException("the JWK to publish carries a private key member");
-        }
-        this.document = Map.of(KEYS_MEMBER,
-                List.of(Collections.unmodifiableMap(new LinkedHashMap<>(publicJwk))));
+    public ClientJwksEndpoint(Map<String, Object> signingJwk) {
+        Objects.requireNonNull(signingJwk, "signingJwk");
+        Map<String, Object> published = new LinkedHashMap<>();
+        for (Map.Entry<String, Object> member : signingJwk.entrySet()) {
+            if (PRIVATE_MEMBERS.contains(member.getKey())) {
+                LOGGER.debug("Withholding JWK member %s=%s from the published key set", member.getKey(),
+                        member.getValue());
+                continue;
+            }
+            published.put(member.getKey(), member.getValue());
+        }
+        this.document = Map.of(KEYS_MEMBER, List.of(Collections.unmodifiableMap(published)));
     }

